import sqlite3
from datetime import datetime, timezone

from agents import function_tool

DB_PATH = "ticketing.db"
_ALLOWED_ROLES = {"gate_scanner", "box_office", "event_manager"}


@function_tool
def grant_event_staff_role(event_id: int, staff_username: str, role: str) -> str:
    if role not in _ALLOWED_ROLES:
        return f"Invalid role '{role}'. Choose one of: {', '.join(sorted(_ALLOWED_ROLES))}."
    if not staff_username or not staff_username.strip():
        return "A staff username is required."
    if event_id <= 0:
        return "event_id must be a positive integer."
    conn = sqlite3.connect(DB_PATH)
    event = conn.execute("SELECT name FROM events WHERE id = ?", (event_id,)).fetchone()
    if event is None:
        conn.close()
        return f"Event {event_id} not found."
    staff = conn.execute(
        "SELECT id, active FROM staff WHERE username = ?", (staff_username.strip(),)
    ).fetchone()
    if staff is None:
        conn.close()
        return f"Staff member '{staff_username}' not found."
    if not staff[1]:
        conn.close()
        return f"Staff member '{staff_username}' is deactivated and cannot be given roles."
    conn.execute(
        "INSERT OR REPLACE INTO event_staff_roles (event_id, staff_id, role, granted_at) VALUES (?, ?, ?, ?)",
        (event_id, staff[0], role, datetime.now(timezone.utc).isoformat()),
    )
    conn.commit()
    conn.close()
    return f"Granted '{role}' to {staff_username} for event '{event[0]}'."
